+#[must_use]
+pub fn invite_url(
+    identity: &Identity,
+    window: &PairingWindow,
+    address: Option<IpAddr>,
+    port: u16,
+) -> String {
+    let host = match address.filter(|_| identity.listen.lan) {
+        Some(IpAddr::V6(ip)) => format!("[{ip}]"),
+        Some(ip) => ip.to_string(),
+        None => "127.0.0.1".to_owned(),
+    };
+    format!(
+        "https://{host}:{port}/#code={}&key={}&id={}",
+        window.code, identity.spki_sha256, identity.server_id
+    )
+}
