content.content:
1	'use strict';
2	
3	// The web control surface. It speaks the protocol the headset speaks
4	// (docs/remote-client.md): pair once from the URL's fragment, then
5	// read the sessions, a session's last response or screen, and send a
6	// reply. The credential is an HttpOnly cookie the host set, so nothing
7	// here ever holds the token; localStorage keeps only the host's public
8	// identity, which is what tells a revoked pairing from a changed key.
9	//
10	// Everything drawn goes through textContent: agent output never
11	// becomes markup. The pure parts at the top are exported for
12	// `app.test.js` (node --test); the browser half runs only with a
13	// document.
14	
15	// Every path the page asks for, in one place so a test can read them.
16	// `{id}` is a project id in `sessions` and a session id elsewhere.
17	const ROUTES = {
18	  info: '/api/v1/info',
19	  pair: '/api/v1/pair',
20	  me: '/api/v1/me',
21	  projects: '/api/v1/projects',
22	  sessions: '/api/v1/projects/{id}/sessions',
23	  waiting: '/api/v1/waiting',
24	  lastResponse: '/api/v1/sessions/{id}/last-response',
25	  screen: '/api/v1/sessions/{id}/screen?lines=60',
26	  send: '/api/v1/sessions/{id}/send',
27	  events: '/api/v1/events',
28	};
29	
30	const STORAGE_KEY = 'switchboard-host';
31	const POLL_MS = 3000;
32	const POLL_SOCKET_MS = 20000;
33	const RETRY_MIN_MS = 5000;
34	const RETRY_MAX_MS = 60000;
35	
36	// --- pure parts
37	
38	/// The pairing invite in a URL fragment: `#code=…&key=…&id=…`, or null
39	/// when any of the three is missing.
40	function parseFragment(hash) {
41	  const text = (hash || '').replace(/^#/, '');
42	  const out = {};
43	  for (const pair of text.split('&')) {
44	    if (!pair) continue;
45	    const eq = pair.indexOf('=');
46	    const name = eq < 0 ? pair : pair.slice(0, eq);
47	    const value = eq < 0 ? '' : pair.slice(eq + 1);
48	    try {
49	      out[name] = decodeURIComponent(value);
50	    } catch (_) {
51	      out[name] = value;
52	    }
53	  }
54	  if (!out.code || !out.key || !out.id) return null;
55	  return { code: out.code.toUpperCase(), key: out.key.toLowerCase(), id: out.id.toLowerCase() };
56	}
57	
58	/// The device name the host lists this browser under: the browser,
59	/// then the device, from the user agent ("Safari on iPhone").
60	function deviceName(ua, touch) {
61	  const agent = ua || '';
62	  if (!agent) return 'Browser';
63	  let browser = 'Safari';
64	  if (/Edg\//.test(agent)) browser = 'Edge';
65	  else if (/Chrome\//.test(agent)) browser = 'Chrome';
66	  else if (/Firefox\//.test(agent)) browser = 'Firefox';
67	  let device = null;
68	  if (/iPhone/.test(agent)) device = 'iPhone';
69	  else if (/iPad/.test(agent)) device = 'iPad';
70	  else if (/Macintosh/.test(agent)) device = touch ? 'iPad' : 'Mac';
71	  else if (/Android/.test(agent)) device = 'Android';
72	  else if (/Windows/.test(agent)) device = 'Windows';
73	  else if (/Linux/.test(agent)) device = 'Linux';
74	  return device ? browser + ' on ' + device : browser;
75	}
76	
77	/// What a 401 means, read off `/info`, which answers without a
78	/// credential: the host cannot say "revoked" (a revoked token and an
79	/// unknown one are one refusal), so the page tells them apart by
80	/// whether the host is still the one it paired with.
81	function inferUnauthorized(stored, info) {
82	  if (!stored) return 'not_paired';
83	  if (!info) return 'unreachable';
84	  if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
85	    return 'removed';
86	  }
87	  return 'changed';
88	}
89	
90	/// Whether a reply at `reply` ({epoch, revision}) may be applied over
91	/// what is held: a new epoch always, the same epoch at or past the
92	/// held revision; an older reply arriving late is dropped (§4.4).
93	function isCurrent(held, reply) {
94	  if (!held) return true;
95	  if (held.epoch !== reply.epoch) return true;
96	  return reply.revision >= held.revision;
97	}
98	
99	/// Projects with a waiting session first, waiting sessions first within
100	/// a project; otherwise the host's order.
101	function orderProjects(projects, sessionsByProject) {
102	  const groups = projects.map((project) => {
103	    const sessions = (sessionsByProject[project.id] || []).slice();
104	    sessions.sort((a, b) => Number(Boolean(b.waiting)) - Number(Boolean(a.waiting)));
105	    return { project, sessions, waiting: sessions.some((s) => s.waiting) };
106	  });
107	  groups.sort((a, b) => Number(b.waiting) - Number(a.waiting));
108	  return groups;
109	}
110	
111	/// "just now", "3 min ago", "2 h ago", "5 d ago".
112	function sinceText(nowMs, thenMs) {
113	  if (thenMs === null || thenMs === undefined) return '';
114	  const secs = Math.max(0, Math.floor((nowMs - thenMs) / 1000));
115	  if (secs < 60) return 'just now';
116	  if (secs < 3600) return Math.floor(secs / 60) + ' min ago';
117	  if (secs < 86400) return Math.floor(secs / 3600) + ' h ago';
118	  return Math.floor(secs / 86400) + ' d ago';
119	}
120	
121	/// A random hex operation id from `getRandomValues`, which exists
122	/// without a secure context.
123	function randomOp(cryptoObject) {
124	  const bytes = new Uint8Array(16);
125	  cryptoObject.getRandomValues(bytes);
126	  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
127	}
128	
129	/// The sentence for a `/pair` refusal, by its error code.
130	function pairingMessage(code) {
131	  switch (code) {
132	    case 'pairing_closed':
133	      return 'Pairing is not open on the Mac. Open the pairing window again and scan its new code.';
134	    case 'wrong_code':
135	      return 'The code did not match. Open the pairing window again and scan its new code.';
136	    case 'wrong_key':
137	      return 'This address is a different Switchboard than the code was for.';
138	    case 'rate_limited':
139	      return 'Too many attempts. Wait a minute and scan again.';
140	    default:
141	      return 'Pairing failed (' + (code || 'no reply') + ').';
142	  }
143	}
144	
145	if (typeof module !== 'undefined' && module.exports) {
146	  module.exports = {
147	    ROUTES,
148	    parseFragment,
149	    deviceName,
150	    inferUnauthorized,
151	    isCurrent,
152	    orderProjects,
153	    sinceText,
154	    randomOp,
155	    pairingMessage,
156	  };
157	}
158	
159	// --- the browser half
160	
161	if (typeof document !== 'undefined') {
162	  const state = {
163	    stored: loadStored(),
164	    me: null,
165	    groups: [],
166	    held: { list: null, session: null },
167	    open: null,
168	    pending: null,
169	    pollMs: POLL_MS,
170	    pollTimer: null,
171	    socket: null,
172	    retryMs: RETRY_MIN_MS,
173	    retryTimer: null,
174	    refetching: false,
175	    stopped: false,
176	  };
177	
178	  const screen = document.getElementById('screen');
179	  const hostName = document.getElementById('host-name');
180	  const scopeLabel = document.getElementById('scope');
181	  const back = document.getElementById('back');
182	  back.addEventListener('click', () => {
183	    state.open = null;
184	    state.held.session = null;
185	    renderList();
186	  });
187	  document.addEventListener('visibilitychange', schedulePoll);
188	
189	  boot();
190	
191	  function loadStored() {
192	    try {
193	      const text = localStorage.getItem(STORAGE_KEY);
194	      return text ? JSON.parse(text) : null;
195	    } catch (_) {
196	      return null;
197	    }
198	  }
199	
200	  function saveStored(value) {
201	    state.stored = value;
202	    try {
203	      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
204	    } catch (_) {
205	      // Storage is a convenience: without it a 401 reads as "not paired".
206	    }
207	  }
208	
209	  function route(name, id) {
210	    return ROUTES[name].replace('{id}', encodeURIComponent(id || ''));
211	  }
212	
213	  /// One request. A 401 anywhere runs the inference and stops the page;
214	  /// the caller sees the thrown error and does nothing more.
215	  async function api(method, path, body) {
216	    const init = { method, credentials: 'same-origin', cache: 'no-store' };
217	    if (body !== undefined) {
218	      init.headers = { 'Content-Type': 'application/json' };
219	      init.body = JSON.stringify(body);
220	    }
221	    const response = await fetch(path, init);
222	    let json = null;
223	    try {
224	      json = await response.json();
225	    } catch (_) {
226	      json = null;
227	    }
228	    if (response.status === 401) {
229	      await unauthorized();
230	      throw new Error('unauthorized');
231	    }
232	    return { status: response.status, json };
233	  }
234	
235	  function errorCode(json) {
236	    return json && json.error ? json.error.code : null;
237	  }
238	
239	  async function boot() {
240	    const invite = parseFragment(location.hash);
241	    if (invite) {
242	      // Off the address bar first; the host never saw it either.
243	      history.replaceState(null, '', location.pathname);
244	      await pairFrom(invite);
245	      return;
246	    }
247	    await enter();
248	  }
249	
250	  async function pairFrom(invite) {
251	    showNotice('Pairing with this Mac…');
252	    let info;
253	    try {
254	      info = (await api('GET', route('info'))).json;
255	    } catch (_) {
256	      info = null;
257	    }
258	    const body = info && info.body;
259	    if (!body) {
260	      showNotice("Can't reach the host at this address.", true);
261	      return;
262	    }
263	    if (body.spki_sha256 !== invite.key || String(body.server_id).toLowerCase() !== invite.id) {
264	      showNotice(pairingMessage('wrong_key'), true);
265	      return;
266	    }
267	    const touch = navigator.maxTouchPoints > 1;
268	    let reply;
269	    try {
270	      reply = await api('POST', route('pair'), {
271	        code: invite.code,
272	        spki_sha256: invite.key,
273	        device_name: deviceName(navigator.userAgent, touch),
274	        transport: 'cookie',
275	      });
276	    } catch (_) {
277	      showNotice(pairingMessage(null), true);
278	      return;
279	    }
280	    if (reply.status !== 200) {
281	      showNotice(pairingMessage(errorCode(reply.json)), true);
282	      return;
283	    }
284	    saveStored({
285	      server_id: String(body.server_id).toLowerCase(),
286	      spki_sha256: body.spki_sha256,
287	      server_name: body.server_name,
288	    });
289	    await enter();
290	  }
291	
292	  /// Rehydrate: who am I to this host. Anything but 200 is handled by
293	  /// `api` (a 401) or shown.
294	  async function enter() {
295	    let reply;
296	    try {
297	      reply = await api('GET', route('me'));
298	    } catch (_) {
299	      return;
300	    }
301	    if (reply.status !== 200 || !reply.json || !reply.json.body) {
302	      showNotice("Can't reach the host at this address.", true);
303	      return;
304	    }
305	    applyMe(reply.json.body);
306	    await refetchAll();
307	    schedulePoll();
308	    connectSocket();
309	  }
310	
311	  function applyMe(me) {
312	    state.me = me;
313	    hostName.textContent = me.server_name || 'Switchboard';
314	    scopeLabel.textContent = me.scope || '';
315	    if (state.stored) {
316	      saveStored(Object.assign({}, state.stored, { server_name: me.server_name }));
317	    }
318	  }
319	
320	  /// The page's answer to a 401: read `/info` and say what it means.
321	  async function unauthorized() {
322	    stop();
323	    let info = null;
324	    try {
325	      const response = await fetch(route('info'), { credentials: 'omit', cache: 'no-store' });
326	      const json = await response.json();
327	      info = json && json.body ? json.body : null;
328	    } catch (_) {
329	      info = null;
330	    }
331	    switch (inferUnauthorized(state.stored, info)) {
332	      case 'not_paired':
333	        showNotPaired();
334	        break;
335	      case 'removed':
336	        showNotice('This device was removed on the host. Pair again from its pairing window.', true);
337	        break;
338	      case 'changed':
339	        showNotice('The host at this address is not the one this device paired with (its identity changed). Pair again from its pairing window.', true);
340	        break;
341	      default:
342	        showNotice("Can't reach the host at this address.", true);
343	    }
344	  }
345	
346	  function stop() {
347	    state.stopped = true;
348	    if (state.pollTimer) clearTimeout(state.pollTimer);
349	    if (state.retryTimer) clearTimeout(state.retryTimer);
350	    state.pollTimer = null;
351	    state.retryTimer = null;
352	    if (state.socket) {
353	      const socket = state.socket;
354	      state.socket = null;
355	      try {
356	        socket.close();
357	      } catch (_) {
358	        // Already closed.
359	      }
360	    }
361	  }
362	
363	  // --- refresh
364	
365	  function schedulePoll() {
366	    if (state.stopped || !state.me) return;
367	    if (state.pollTimer) clearTimeout(state.pollTimer);
368	    state.pollTimer = null;
369	    if (document.visibilityState !== 'visible') return;
370	    state.pollTimer = setTimeout(poll, state.pollMs);
371	  }
372	
373	  async function poll() {
374	    state.pollTimer = null;
375	    if (state.stopped) return;
376	    try {
377	      const reply = await api('GET', route('waiting'));
378	      const held = state.held.list;
379	      if (reply.status === 200 && reply.json && held
380	        && (reply.json.epoch !== held.epoch || reply.json.revision !== held.revision)) {
381	        await refetchAll();
382	      } else if (reply.status === 200 && reply.json && !held) {
383	        await refetchAll();
384	      }
385	    } catch (_) {
386	      return;
387	    }
388	    schedulePoll();
389	  }
390	
391	  /// The list, and the open session's content, read again. One at a
392	  /// time: a refetch asked for while one runs is folded into it.
393	  async function refetchAll() {
394	    if (state.refetching) {
395	      state.refetchAgain = true;
396	      return;
397	    }
398	    state.refetching = true;
399	    try {
400	      do {
401	        state.refetchAgain = false;
402	        await loadList();
403	        if (state.open) await loadSession(state.open);
404	      } while (state.refetchAgain && !state.stopped);
405	    } catch (_) {
406	      // A 401 stopped the page; a network error waits for the next poll.
407	    } finally {
408	      state.refetching = false;
409	    }
410	  }
411	
412	  async function loadList() {
413	    const projectsReply = await api('GET', route('projects'));
414	    if (projectsReply.status !== 200 || !projectsReply.json) return;
415	    let newest = { epoch: projectsReply.json.epoch, revision: projectsReply.json.revision };
416	    if (!isCurrent(state.held.list, newest)) return;
417	    const projects = (projectsReply.json.body && projectsReply.json.body.projects) || [];
418	    const sessionsByProject = {};
419	    for (const project of projects) {
420	      const reply = await api('GET', route('sessions', project.id));
421	      if (reply.status !== 200 || !reply.json) continue;
422	      sessionsByProject[project.id] = (reply.json.body && reply.json.body.sessions) || [];
423	      if (reply.json.epoch === newest.epoch && reply.json.revision > newest.revision) {
424	        newest = { epoch: reply.json.epoch, revision: reply.json.revision };
425	      }
426	    }
427	    state.held.list = newest;
428	    state.groups = orderProjects(projects, sessionsByProject);
429	    if (!state.open) renderList();
430	  }
431	
432	  function findSession(id) {
433	    for (const group of state.groups) {
434	      for (const session of group.sessions) {
435	        if (session.id === id) return session;
436	      }
437	    }
438	    return null;
439	  }
440	
441	  async function loadSession(id) {
442	    const session = findSession(id);
443	    if (!session) {
444	      state.open = null;
445	      renderList();
446	      return;
447	    }
448	    const path = session.kind === 'claude' ? route('lastResponse', id) : route('screen', id);
449	    const reply = await api('GET', path);
450	    if (!reply.json) return;
451	    if (reply.status === 200) {
452	      const at = { epoch: reply.json.epoch, revision: reply.json.revision };
453	      if (!isCurrent(state.held.session, at)) return;
454	      state.held.session = at;
455	      renderSession(session, reply.json.body.text || '', false);
456	    } else {
457	      renderSession(session, (reply.json.error && reply.json.error.message) || 'Nothing to show.', true);
458	    }
459	  }
460	
461	  // --- the events socket, an enhancement over the poll
462	
463	  function connectSocket() {
464	    if (state.stopped || state.socket || typeof WebSocket === 'undefined') return;
465	    let socket;
466	    try {
467	      socket = new WebSocket('wss://' + location.host + route('events'));
468	    } catch (_) {
469	      scheduleRetry();
470	      return;
471	    }
472	    state.socket = socket;
473	    socket.addEventListener('open', () => {
474	      state.retryMs = RETRY_MIN_MS;
475	      state.pollMs = POLL_SOCKET_MS;
476	      schedulePoll();
477	    });
478	    socket.addEventListener('message', (event) => {
479	      let frame;
480	      try {
481	        frame = JSON.parse(event.data);
482	      } catch (_) {
483	        return;
484	      }
485	      if (frame.type === 'changed' || frame.type === 'removed') {
486	        refetchAll();
487	      } else if (frame.type === 'resync_required') {
488	        refetchAll();
489	      }
490	    });
491	    const ended = () => {
492	      if (state.socket !== socket) return;
493	      state.socket = null;
494	      state.pollMs = POLL_MS;
495	      refetchAll();
496	      schedulePoll();
497	      scheduleRetry();
498	    };
499	    socket.addEventListener('close', ended);
500	    socket.addEventListener('error', ended);
501	  }
502	
503	  function scheduleRetry() {
504	    if (state.stopped || state.retryTimer) return;
505	    state.retryTimer = setTimeout(() => {
506	      state.retryTimer = null;
507	      connectSocket();
508	    }, state.retryMs);
509	    state.retryMs = Math.min(state.retryMs * 2, RETRY_MAX_MS);
510	  }
511	
512	  // --- drawing, textContent only
513	
514	  function el(tag, className, text) {
515	    const node = document.createElement(tag);
516	    if (className) node.className = className;
517	    if (text !== undefined) node.textContent = text;
518	    return node;
519	  }
520	
521	  function clear() {
522	    while (screen.firstChild) screen.removeChild(screen.firstChild);
523	  }
524	
525	  function showNotice(text, isError) {
526	    clear();
527	    back.hidden = true;
528	    screen.appendChild(el('div', isError ? 'notice error' : 'notice', text));
529	  }
530	
531	  function showNotPaired() {
532	    clear();
533	    back.hidden = true;
534	    hostName.textContent = 'Switchboard';
535	    scopeLabel.textContent = '';
536	    screen.appendChild(el('div', 'notice', 'Not paired.'));
537	    screen.appendChild(el('p', 'small',
538	      'Open the Remote devices dialog on the Mac, allow pairing, and scan its code with this phone.'));
539	  }
540	
541	  function renderList() {
542	    clear();
543	    back.hidden = true;
544	    const now = Date.now();
545	    if (state.groups.length === 0) {
546	      screen.appendChild(el('p', 'small', 'No projects on this host.'));
547	      return;
548	    }
549	    for (const group of state.groups) {
550	      screen.appendChild(el('h2', null, group.project.name));
551	      if (group.sessions.length === 0) {
552	        screen.appendChild(el('p', 'small', 'No sessions.'));
553	        continue;
554	      }
555	      for (const session of group.sessions) {
556	        const row = el('button', session.waiting ? 'row waiting' : 'row');
557	        row.type = 'button';
558	        if (session.waiting) {
559	          const reason = session.waiting_reason ? ': ' + session.waiting_reason : '';
560	          row.appendChild(el('span', 'mark', 'Waiting on you' + reason));
561	        }
562	        row.appendChild(el('span', 'name', session.name));
563	        const since = sinceText(now, session.last_activity_ms);
564	        row.appendChild(el('span', 'meta',
565	          session.kind + ' · ' + session.card + (since ? ' · ' + since : '')));
566	        row.addEventListener('click', () => openSession(session.id));
567	        screen.appendChild(row);
568	      }
569	    }
570	  }
571	
572	  async function openSession(id) {
573	    state.open = id;
574	    state.held.session = null;
575	    const session = findSession(id);
576	    if (session) renderSession(session, 'Loading…', true);
577	    try {
578	      await loadSession(id);
579	    } catch (_) {
580	      // Handled by `api`.
581	    }
582	  }
583	
584	  function renderSession(session, text, provisional) {
585	    clear();
586	    back.hidden = false;
587	    const title = el('h2', null, session.name);
588	    screen.appendChild(title);
589	    if (session.waiting) {
590	      const reason = session.waiting_reason ? ': ' + session.waiting_reason : '';
591	      screen.appendChild(el('p', 'mark', 'Waiting on you' + reason));
592	    }
593	    screen.appendChild(el('p', 'small',
594	      session.kind === 'claude' ? 'Last response' : 'Screen'));
595	    screen.appendChild(el('pre', 'text', text));
596	    if (provisional) return;
597	    const canSend = state.me && state.me.scope === 'control';
598	    if (!canSend) {
599	      screen.appendChild(el('p', 'small', 'This device reads only. Raise its scope on the Mac to reply.'));
600	      return;
601	    }
602	    if (session.prompt_refusal) {
603	      screen.appendChild(el('p', 'small', session.prompt_refusal));
604	      return;
605	    }
606	    const compose = el('div', 'compose');
607	    const box = document.createElement('textarea');
608	    box.placeholder = 'Reply…';
609	    if (state.pending && state.pending.session === session.id) box.value = state.pending.text;
610	    const status = el('div', 'status', '');
611	    const send = el('button', 'primary', 'Send');
612	    send.type = 'button';
613	    send.addEventListener('click', () => sendReply(session, box, send, status));
614	    compose.appendChild(box);
615	    compose.appendChild(send);
616	    compose.appendChild(status);
617	    screen.appendChild(compose);
618	  }
619	
620	  /// Send is `POST send {op, text}`. The op is kept until a reply lands,
621	  /// so a retry after a dropped reply repeats the same op and is
622	  /// answered from the host's log rather than typed twice.
623	  async function sendReply(session, box, send, status) {
624	    const text = box.value;
625	    if (!text.trim()) return;
626	    if (!state.pending || state.pending.session !== session.id || state.pending.text !== text) {
627	      state.pending = { session: session.id, text, op: randomOp(crypto) };
628	    }
629	    send.disabled = true;
630	    status.textContent = 'Sending…';
631	    let reply;
632	    try {
633	      reply = await api('POST', route('send', session.id), { op: state.pending.op, text });
634	    } catch (e) {
635	      send.disabled = false;
636	      if (e && e.message === 'unauthorized') return;
637	      status.textContent = 'No reply from the host. Tap Send to retry.';
638	      return;
639	    }
640	    send.disabled = false;
641	    if (reply.status === 200) {
642	      state.pending = null;
643	      box.value = '';
644	      status.textContent = 'Sent.';
645	      refetchAll();
646	      return;
647	    }
648	    const code = errorCode(reply.json);
649	    if (code === 'scope') {
650	      // The scope moved on the Mac; what the page may do follows /me.
651	      state.pending = null;
652	      try {
653	        const me = await api('GET', route('me'));
654	        if (me.status === 200 && me.json && me.json.body) applyMe(me.json.body);
655	      } catch (_) {
656	        return;
657	      }
658	      await refetchAll();
659	      return;
660	    }
661	    state.pending = null;
662	    status.textContent = (reply.json && reply.json.error && reply.json.error.message) || 'Not sent.';
663	  }
664	}
