'use strict';

// The web control surface. It speaks the protocol the headset speaks
// (docs/remote-client.md): pair once from the URL's fragment, then
// read the sessions, a session's last response or screen, and send a
// reply. The credential is an HttpOnly cookie the host set, so nothing
// here ever holds the token; localStorage keeps only the host's public
// identity, which is what tells a revoked pairing from a changed key.
//
// Everything drawn goes through textContent: agent output never
// becomes markup. The pure parts at the top are exported for
// `app.test.js` (node --test); the browser half runs only with a
// document.

// Every path the page asks for, in one place so a test can read them.
// `{id}` is a project id in `sessions` and a session id elsewhere.
const ROUTES = {
  info: '/api/v1/info',
  pair: '/api/v1/pair',
  me: '/api/v1/me',
  projects: '/api/v1/projects',
  sessions: '/api/v1/projects/{id}/sessions',
  waiting: '/api/v1/waiting',
  lastResponse: '/api/v1/sessions/{id}/last-response',
  screen: '/api/v1/sessions/{id}/screen?lines=60',
  send: '/api/v1/sessions/{id}/send',
  events: '/api/v1/events',
};

const STORAGE_KEY = 'switchboard-host';
const POLL_MS = 3000;
const POLL_SOCKET_MS = 20000;
const RETRY_MIN_MS = 5000;
const RETRY_MAX_MS = 60000;

// --- pure parts

/// The pairing invite in a URL fragment: `#code=…&key=…&id=…`, or null
/// when any of the three is missing.
function parseFragment(hash) {
  const text = (hash || '').replace(/^#/, '');
  const out = {};
  for (const pair of text.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const name = eq < 0 ? pair : pair.slice(0, eq);
    const value = eq < 0 ? '' : pair.slice(eq + 1);
    try {
      out[name] = decodeURIComponent(value);
    } catch (_) {
      out[name] = value;
    }
  }
  if (!out.code || !out.key || !out.id) return null;
  return { code: out.code.toUpperCase(), key: out.key.toLowerCase(), id: out.id.toLowerCase() };
}

/// The device name the host lists this browser under: the browser,
/// then the device, from the user agent ("Safari on iPhone").
function deviceName(ua, touch) {
  const agent = ua || '';
  if (!agent) return 'Browser';
  let browser = 'Safari';
  if (/Edg\//.test(agent)) browser = 'Edge';
  else if (/Chrome\//.test(agent)) browser = 'Chrome';
  else if (/Firefox\//.test(agent)) browser = 'Firefox';
  let device = null;
  if (/iPhone/.test(agent)) device = 'iPhone';
  else if (/iPad/.test(agent)) device = 'iPad';
  else if (/Macintosh/.test(agent)) device = touch ? 'iPad' : 'Mac';
  else if (/Android/.test(agent)) device = 'Android';
  else if (/Windows/.test(agent)) device = 'Windows';
  else if (/Linux/.test(agent)) device = 'Linux';
  return device ? browser + ' on ' + device : browser;
}

/// What a 401 means, read off `/info`, which answers without a
/// credential: the host cannot say "revoked" (a revoked token and an
/// unknown one are one refusal), so the page tells them apart by
/// whether the host is still the one it paired with.
function inferUnauthorized(stored, info) {
  if (!stored) return 'not_paired';
  if (!info) return 'unreachable';
  if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
    return 'removed';
  }
  return 'changed';
}

/// Whether a reply at `reply` ({epoch, revision}) may be applied over
/// what is held: a new epoch always, the same epoch at or past the
/// held revision; an older reply arriving late is dropped (§4.4).
function isCurrent(held, reply) {
  if (!held) return true;
  if (held.epoch !== reply.epoch) return true;
  return reply.revision >= held.revision;
}

/// Projects with a waiting session first, waiting sessions first within
/// a project; otherwise the host's order.
function orderProjects(projects, sessionsByProject) {
  const groups = projects.map((project) => {
    const sessions = (sessionsByProject[project.id] || []).slice();
    sessions.sort((a, b) => Number(Boolean(b.waiting)) - Number(Boolean(a.waiting)));
    return { project, sessions, waiting: sessions.some((s) => s.waiting) };
  });
  groups.sort((a, b) => Number(b.waiting) - Number(a.waiting));
  return groups;
}

/// "just now", "3 min ago", "2 h ago", "5 d ago".
function sinceText(nowMs, thenMs) {
  if (thenMs === null || thenMs === undefined) return '';
  const secs = Math.max(0, Math.floor((nowMs - thenMs) / 1000));
  if (secs < 60) return 'just now';
  if (secs < 3600) return Math.floor(secs / 60) + ' min ago';
  if (secs < 86400) return Math.floor(secs / 3600) + ' h ago';
  return Math.floor(secs / 86400) + ' d ago';
}

/// A random hex operation id from `getRandomValues`, which exists
/// without a secure context.
function randomOp(cryptoObject) {
  const bytes = new Uint8Array(16);
  cryptoObject.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

/// The sentence for a `/pair` refusal, by its error code.
function pairingMessage(code) {
  switch (code) {
    case 'pairing_closed':
      return 'Pairing is not open on the Mac. Open the pairing window again and scan its new code.';
    case 'wrong_code':
      return 'The code did not match. Open the pairing window again and scan its new code.';
    case 'wrong_key':
      return 'This address is a different Switchboard than the code was for.';
    case 'rate_limited':
      return 'Too many attempts. Wait a minute and scan again.';
    default:
      return 'Pairing failed (' + (code || 'no reply') + ').';
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    ROUTES,
    parseFragment,
    deviceName,
    inferUnauthorized,
    isCurrent,
    orderProjects,
    sinceText,
    randomOp,
    pairingMessage,
  };
}

// --- the browser half

if (typeof document !== 'undefined') {
  const state = {
    stored: loadStored(),
    me: null,
    groups: [],
    held: { list: null, session: null },
    open: null,
    pending: null,
    pollMs: POLL_MS,
    pollTimer: null,
    socket: null,
    retryMs: RETRY_MIN_MS,
    retryTimer: null,
    refetching: false,
    stopped: false,
  };

  const screen = document.getElementById('screen');
  const hostName = document.getElementById('host-name');
  const scopeLabel = document.getElementById('scope');
  const back = document.getElementById('back');
  back.addEventListener('click', () => {
    state.open = null;
    state.held.session = null;
    renderList();
  });
  document.addEventListener('visibilitychange', schedulePoll);

  boot();

  function loadStored() {
    try {
      const text = localStorage.getItem(STORAGE_KEY);
      return text ? JSON.parse(text) : null;
    } catch (_) {
      return null;
    }
  }

  function saveStored(value) {
    state.stored = value;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    } catch (_) {
      // Storage is a convenience: without it a 401 reads as "not paired".
    }
  }

  function route(name, id) {
    return ROUTES[name].replace('{id}', encodeURIComponent(id || ''));
  }

  /// One request. A 401 anywhere runs the inference and stops the page;
  /// the caller sees the thrown error and does nothing more.
  async function api(method, path, body) {
    const init = { method, credentials: 'same-origin', cache: 'no-store' };
    if (body !== undefined) {
      init.headers = { 'Content-Type': 'application/json' };
      init.body = JSON.stringify(body);
    }
    const response = await fetch(path, init);
    let json = null;
    try {
      json = await response.json();
    } catch (_) {
      json = null;
    }
    if (response.status === 401) {
      await unauthorized();
      throw new Error('unauthorized');
    }
    return { status: response.status, json };
  }

  function errorCode(json) {
    return json && json.error ? json.error.code : null;
  }

  async function boot() {
    const invite = parseFragment(location.hash);
    if (invite) {
      // Off the address bar first; the host never saw it either.
      history.replaceState(null, '', location.pathname);
      await pairFrom(invite);
      return;
    }
    await enter();
  }

  async function pairFrom(invite) {
    showNotice('Pairing with this Mac…');
    let info;
    try {
      info = (await api('GET', route('info'))).json;
    } catch (_) {
      info = null;
    }
    const body = info && info.body;
    if (!body) {
      showNotice("Can't reach the host at this address.", true);
      return;
    }
    if (body.spki_sha256 !== invite.key || String(body.server_id).toLowerCase() !== invite.id) {
      showNotice(pairingMessage('wrong_key'), true);
      return;
    }
    const touch = navigator.maxTouchPoints > 1;
    let reply;
    try {
      reply = await api('POST', route('pair'), {
        code: invite.code,
        spki_sha256: invite.key,
        device_name: deviceName(navigator.userAgent, touch),
        transport: 'cookie',
      });
    } catch (_) {
      showNotice(pairingMessage(null), true);
      return;
    }
    if (reply.status !== 200) {
      showNotice(pairingMessage(errorCode(reply.json)), true);
      return;
    }
    saveStored({
      server_id: String(body.server_id).toLowerCase(),
      spki_sha256: body.spki_sha256,
      server_name: body.server_name,
    });
    await enter();
  }

  /// Rehydrate: who am I to this host. Anything but 200 is handled by
  /// `api` (a 401) or shown.
  async function enter() {
    let reply;
    try {
      reply = await api('GET', route('me'));
    } catch (_) {
      return;
    }
    if (reply.status !== 200 || !reply.json || !reply.json.body) {
      showNotice("Can't reach the host at this address.", true);
      return;
    }
    applyMe(reply.json.body);
    await refetchAll();
    schedulePoll();
    connectSocket();
  }

  function applyMe(me) {
    state.me = me;
    hostName.textContent = me.server_name || 'Switchboard';
    scopeLabel.textContent = me.scope || '';
    if (state.stored) {
      saveStored(Object.assign({}, state.stored, { server_name: me.server_name }));
    }
  }

  /// The page's answer to a 401: read `/info` and say what it means.
  async function unauthorized() {
    stop();
    let info = null;
    try {
      const response = await fetch(route('info'), { credentials: 'omit', cache: 'no-store' });
      const json = await response.json();
      info = json && json.body ? json.body : null;
    } catch (_) {
      info = null;
    }
    switch (inferUnauthorized(state.stored, info)) {
      case 'not_paired':
        showNotPaired();
        break;
      case 'removed':
        showNotice('This device was removed on the host. Pair again from its pairing window.', true);
        break;
      case 'changed':
        showNotice('The host at this address is not the one this device paired with (its identity changed). Pair again from its pairing window.', true);
        break;
      default:
        showNotice("Can't reach the host at this address.", true);
    }
  }

  function stop() {
    state.stopped = true;
    if (state.pollTimer) clearTimeout(state.pollTimer);
    if (state.retryTimer) clearTimeout(state.retryTimer);
    state.pollTimer = null;
    state.retryTimer = null;
    if (state.socket) {
      const socket = state.socket;
      state.socket = null;
      try {
        socket.close();
      } catch (_) {
        // Already closed.
      }
    }
  }

  // --- refresh

  function schedulePoll() {
    if (state.stopped || !state.me) return;
    if (state.pollTimer) clearTimeout(state.pollTimer);
    state.pollTimer = null;
    if (document.visibilityState !== 'visible') return;
    state.pollTimer = setTimeout(poll, state.pollMs);
  }

  async function poll() {
    state.pollTimer = null;
    if (state.stopped) return;
    try {
      const reply = await api('GET', route('waiting'));
      const held = state.held.list;
      if (reply.status === 200 && reply.json && held
        && (reply.json.epoch !== held.epoch || reply.json.revision !== held.revision)) {
        await refetchAll();
      } else if (reply.status === 200 && reply.json && !held) {
        await refetchAll();
      }
    } catch (_) {
      return;
    }
    schedulePoll();
  }

  /// The list, and the open session's content, read again. One at a
  /// time: a refetch asked for while one runs is folded into it.
  async function refetchAll() {
    if (state.refetching) {
      state.refetchAgain = true;
      return;
    }
    state.refetching = true;
    try {
      do {
        state.refetchAgain = false;
        await loadList();
        if (state.open) await loadSession(state.open);
      } while (state.refetchAgain && !state.stopped);
    } catch (_) {
      // A 401 stopped the page; a network error waits for the next poll.
    } finally {
      state.refetching = false;
    }
  }

  async function loadList() {
    const projectsReply = await api('GET', route('projects'));
    if (projectsReply.status !== 200 || !projectsReply.json) return;
    let newest = { epoch: projectsReply.json.epoch, revision: projectsReply.json.revision };
    if (!isCurrent(state.held.list, newest)) return;
    const projects = (projectsReply.json.body && projectsReply.json.body.projects) || [];
    const sessionsByProject = {};
    for (const project of projects) {
      const reply = await api('GET', route('sessions', project.id));
      if (reply.status !== 200 || !reply.json) continue;
      sessionsByProject[project.id] = (reply.json.body && reply.json.body.sessions) || [];
      if (reply.json.epoch === newest.epoch && reply.json.revision > newest.revision) {
        newest = { epoch: reply.json.epoch, revision: reply.json.revision };
      }
    }
    state.held.list = newest;
    state.groups = orderProjects(projects, sessionsByProject);
    if (!state.open) renderList();
  }

  function findSession(id) {
    for (const group of state.groups) {
      for (const session of group.sessions) {
        if (session.id === id) return session;
      }
    }
    return null;
  }

  async function loadSession(id) {
    const session = findSession(id);
    if (!session) {
      state.open = null;
      renderList();
      return;
    }
    const path = session.kind === 'claude' ? route('lastResponse', id) : route('screen', id);
    const reply = await api('GET', path);
    if (!reply.json) return;
    if (reply.status === 200) {
      const at = { epoch: reply.json.epoch, revision: reply.json.revision };
      if (!isCurrent(state.held.session, at)) return;
      state.held.session = at;
      renderSession(session, reply.json.body.text || '', false);
    } else {
      renderSession(session, (reply.json.error && reply.json.error.message) || 'Nothing to show.', true);
    }
  }

  // --- the events socket, an enhancement over the poll

  function connectSocket() {
    if (state.stopped || state.socket || typeof WebSocket === 'undefined') return;
    let socket;
    try {
      socket = new WebSocket('wss://' + location.host + route('events'));
    } catch (_) {
      scheduleRetry();
      return;
    }
    state.socket = socket;
    socket.addEventListener('open', () => {
      state.retryMs = RETRY_MIN_MS;
      state.pollMs = POLL_SOCKET_MS;
      schedulePoll();
    });
    socket.addEventListener('message', (event) => {
      let frame;
      try {
        frame = JSON.parse(event.data);
      } catch (_) {
        return;
      }
      if (frame.type === 'changed' || frame.type === 'removed') {
        refetchAll();
      } else if (frame.type === 'resync_required') {
        refetchAll();
      }
    });
    const ended = () => {
      if (state.socket !== socket) return;
      state.socket = null;
      state.pollMs = POLL_MS;
      refetchAll();
      schedulePoll();
      scheduleRetry();
    };
    socket.addEventListener('close', ended);
    socket.addEventListener('error', ended);
  }

  function scheduleRetry() {
    if (state.stopped || state.retryTimer) return;
    state.retryTimer = setTimeout(() => {
      state.retryTimer = null;
      connectSocket();
    }, state.retryMs);
    state.retryMs = Math.min(state.retryMs * 2, RETRY_MAX_MS);
  }

  // --- drawing, textContent only

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function clear() {
    while (screen.firstChild) screen.removeChild(screen.firstChild);
  }

  function showNotice(text, isError) {
    clear();
    back.hidden = true;
    screen.appendChild(el('div', isError ? 'notice error' : 'notice', text));
  }

  function showNotPaired() {
    clear();
    back.hidden = true;
    hostName.textContent = 'Switchboard';
    scopeLabel.textContent = '';
    screen.appendChild(el('div', 'notice', 'Not paired.'));
    screen.appendChild(el('p', 'small',
      'Open the Remote devices dialog on the Mac, allow pairing, and scan its code with this phone.'));
  }

  function renderList() {
    clear();
    back.hidden = true;
    const now = Date.now();
    if (state.groups.length === 0) {
      screen.appendChild(el('p', 'small', 'No projects on this host.'));
      return;
    }
    for (const group of state.groups) {
      screen.appendChild(el('h2', null, group.project.name));
      if (group.sessions.length === 0) {
        screen.appendChild(el('p', 'small', 'No sessions.'));
        continue;
      }
      for (const session of group.sessions) {
        const row = el('button', session.waiting ? 'row waiting' : 'row');
        row.type = 'button';
        if (session.waiting) {
          const reason = session.waiting_reason ? ': ' + session.waiting_reason : '';
          row.appendChild(el('span', 'mark', 'Waiting on you' + reason));
        }
        row.appendChild(el('span', 'name', session.name));
        const since = sinceText(now, session.last_activity_ms);
        row.appendChild(el('span', 'meta',
          session.kind + ' · ' + session.card + (since ? ' · ' + since : '')));
        row.addEventListener('click', () => openSession(session.id));
        screen.appendChild(row);
      }
    }
  }

  async function openSession(id) {
    state.open = id;
    state.held.session = null;
    const session = findSession(id);
    if (session) renderSession(session, 'Loading…', true);
    try {
      await loadSession(id);
    } catch (_) {
      // Handled by `api`.
    }
  }

  function renderSession(session, text, provisional) {
    clear();
    back.hidden = false;
    const title = el('h2', null, session.name);
    screen.appendChild(title);
    if (session.waiting) {
      const reason = session.waiting_reason ? ': ' + session.waiting_reason : '';
      screen.appendChild(el('p', 'mark', 'Waiting on you' + reason));
    }
    screen.appendChild(el('p', 'small',
      session.kind === 'claude' ? 'Last response' : 'Screen'));
    screen.appendChild(el('pre', 'text', text));
    if (provisional) return;
    const canSend = state.me && state.me.scope === 'control';
    if (!canSend) {
      screen.appendChild(el('p', 'small', 'This device reads only. Raise its scope on the Mac to reply.'));
      return;
    }
    if (session.prompt_refusal) {
      screen.appendChild(el('p', 'small', session.prompt_refusal));
      return;
    }
    const compose = el('div', 'compose');
    const box = document.createElement('textarea');
    box.placeholder = 'Reply…';
    if (state.pending && state.pending.session === session.id) box.value = state.pending.text;
    const status = el('div', 'status', '');
    const send = el('button', 'primary', 'Send');
    send.type = 'button';
    send.addEventListener('click', () => sendReply(session, box, send, status));
    compose.appendChild(box);
    compose.appendChild(send);
    compose.appendChild(status);
    screen.appendChild(compose);
  }

  /// Send is `POST send {op, text}`. The op is kept until a reply lands,
  /// so a retry after a dropped reply repeats the same op and is
  /// answered from the host's log rather than typed twice.
  async function sendReply(session, box, send, status) {
    const text = box.value;
    if (!text.trim()) return;
    if (!state.pending || state.pending.session !== session.id || state.pending.text !== text) {
      state.pending = { session: session.id, text, op: randomOp(crypto) };
    }
    send.disabled = true;
    status.textContent = 'Sending…';
    let reply;
    try {
      reply = await api('POST', route('send', session.id), { op: state.pending.op, text });
    } catch (e) {
      send.disabled = false;
      if (e && e.message === 'unauthorized') return;
      status.textContent = 'No reply from the host. Tap Send to retry.';
      return;
    }
    send.disabled = false;
    if (reply.status === 200) {
      state.pending = null;
      box.value = '';
      status.textContent = 'Sent.';
      refetchAll();
      return;
    }
    const code = errorCode(reply.json);
    if (code === 'scope') {
      // The scope moved on the Mac; what the page may do follows /me.
      state.pending = null;
      try {
        const me = await api('GET', route('me'));
        if (me.status === 200 && me.json && me.json.body) applyMe(me.json.body);
      } catch (_) {
        return;
      }
      await refetchAll();
      return;
    }
    state.pending = null;
    status.textContent = (reply.json && reply.json.error && reply.json.error.message) || 'Not sent.';
  }
}

